import{_ as a,o as e,c as l,ag as i}from"./chunks/framework.i8sMDeRW.js";const b=JSON.parse('{"title":"LLM 工程与微调教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-llm-engineering/index.md","filePath":"guide/12-llm-engineering/index.md","lastUpdated":1779767567000}'),r={name:"guide/12-llm-engineering/index.md"};function d(n,t,o,h,c,s){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="llm-工程与微调教程" tabindex="-1">LLM 工程与微调教程 <a class="header-anchor" href="#llm-工程与微调教程" aria-label="Permalink to &quot;LLM 工程与微调教程&quot;">​</a></h1><blockquote><p>从产品经理视角出发，用简单中文、生活类比和小项目，系统学习现代 LLM 工程、微调、RAG、Agent、部署和评估。</p></blockquote><hr><h2 id="这个教程适合谁" tabindex="-1">这个教程适合谁？ <a class="header-anchor" href="#这个教程适合谁" aria-label="Permalink to &quot;这个教程适合谁？&quot;">​</a></h2><p>适合想从“会用 AI”升级到“能设计和落地 AI 产品”的人，尤其适合：</p><ul><li>AI 产品经理</li><li>想转型 AI PM 的产品经理</li><li>需要和算法、工程团队协作的业务负责人</li><li>想理解 LLM 工程但不想一开始陷入数学细节的学习者</li></ul><hr><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>学完这个系列，你应该能够：</p><ol><li>解释 LLM、token、embedding、attention、参数、训练、推理等基础概念。</li><li>区分 prompt、RAG、fine-tuning、continued pretraining 分别适合什么问题。</li><li>看懂 LoRA、QLoRA、DPO、RLHF、量化、checkpoint、GGUF 等微调相关词。</li><li>理解本地 AI 工具链，如 Ollama、llama.cpp、vLLM、Hugging Face、Unsloth、Axolotl、PEFT、TRL。</li><li>设计一个基础 RAG 系统，包括 chunking、embedding、vector database、retrieval pipeline。</li><li>设计 AI Agent，包括 system prompt、tool calling、function calling、memory、workflow 和权限控制。</li><li>从产品角度评估模型质量、速度、成本、幻觉风险和上线方案。</li></ol><hr><h2 id="学习方式" tabindex="-1">学习方式 <a class="header-anchor" href="#学习方式" aria-label="Permalink to &quot;学习方式&quot;">​</a></h2><p>每一课都尽量使用固定结构：</p><ol><li>简单定义</li><li>生活类比</li><li>核心原理</li><li>实际例子</li><li>工程应用</li><li>常见误区</li><li>本课总结</li><li>心智模型</li><li>小练习</li><li>小项目</li></ol><p>原则是：</p><blockquote><p>先建立直觉，再补工程细节，最后回到产品落地。</p></blockquote><hr><h2 id="课程路线" tabindex="-1">课程路线 <a class="header-anchor" href="#课程路线" aria-label="Permalink to &quot;课程路线&quot;">​</a></h2><h3 id="第一部分-基础篇" tabindex="-1">第一部分：基础篇 <a class="header-anchor" href="#第一部分-基础篇" aria-label="Permalink to &quot;第一部分：基础篇&quot;">​</a></h3><table tabindex="0"><thead><tr><th>课程</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="./01-llm-basics.html">第 1 课：什么是 LLM？</a></td><td>大语言模型到底是什么？</td></tr><tr><td><a href="./02-token-tokenization-context.html">第 2 课：Token、Tokenization 和上下文窗口</a></td><td>模型为什么不是直接读“字”和“词”？</td></tr><tr><td><a href="./03-embedding-semantic-search.html">第 3 课：Embedding 和语义搜索</a></td><td>文字为什么可以变成“意思坐标”？</td></tr></tbody></table><h3 id="第二部分-模型结构篇" tabindex="-1">第二部分：模型结构篇 <a class="header-anchor" href="#第二部分-模型结构篇" aria-label="Permalink to &quot;第二部分：模型结构篇&quot;">​</a></h3><table tabindex="0"><thead><tr><th>课程</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="./04-transformer-attention.html">第 4 课：Transformer 和 Attention</a></td><td>为什么现代 LLM 这么强？</td></tr><tr><td><a href="./05-parameters-training-inference.html">第 5 课：参数、训练和推理</a></td><td>模型里面的“参数”到底是什么？</td></tr><tr><td><a href="./06-open-source-vs-closed-source.html">第 6 课：开源模型 vs 闭源模型</a></td><td>什么时候用开源，什么时候用闭源？</td></tr></tbody></table><h3 id="第三部分-数据和训练篇" tabindex="-1">第三部分：数据和训练篇 <a class="header-anchor" href="#第三部分-数据和训练篇" aria-label="Permalink to &quot;第三部分：数据和训练篇&quot;">​</a></h3><table tabindex="0"><thead><tr><th>课程</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="./07-sft-datasets-instruction-tuning.html">第 7 课：SFT 数据集和指令微调</a></td><td>如何把模型教成&quot;听指令的助手&quot;？</td></tr><tr><td><a href="./08-preference-data-dpo-rlhf.html">第 8 课：偏好数据、DPO 和 RLHF</a></td><td>如何让模型回答更符合人的偏好？</td></tr><tr><td><a href="./09-synthetic-data-data-curation.html">第 9 课：合成数据和数据清洗</a></td><td>为什么数据质量比数据数量更重要？</td></tr></tbody></table><h3 id="第四部分-微调篇" tabindex="-1">第四部分：微调篇 <a class="header-anchor" href="#第四部分-微调篇" aria-label="Permalink to &quot;第四部分：微调篇&quot;">​</a></h3><table tabindex="0"><thead><tr><th>课程</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="./10-fine-tuning-basics.html">第 10 课：Fine-tuning 基础</a></td><td>微调到底改变了什么？</td></tr><tr><td><a href="./11-lora-adapter-tuning.html">第 11 课：LoRA 和 Adapter Tuning</a></td><td>如何低成本微调大模型？</td></tr><tr><td><a href="./12-qlora-quantization.html">第 12 课：QLoRA 和 Quantization</a></td><td>如何更省显存地训练和部署？</td></tr><tr><td><a href="./13-checkpoint-adapter-gguf.html">第 13 课：Checkpoint、Adapter 和 GGUF</a></td><td>模型文件为什么有这么多格式？</td></tr></tbody></table><h3 id="第五部分-rag、agent、部署与产品篇" tabindex="-1">第五部分：RAG、Agent、部署与产品篇 <a class="header-anchor" href="#第五部分-rag、agent、部署与产品篇" aria-label="Permalink to &quot;第五部分：RAG、Agent、部署与产品篇&quot;">​</a></h3><table tabindex="0"><thead><tr><th>课程</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="./14-rag-basics.html">第 14 课：RAG 基础</a></td><td>如何让模型基于你的资料回答？</td></tr><tr><td><a href="./15-tool-calling-agent.html">第 15 课：Tool Calling 和 Agent</a></td><td>如何让模型不只回答，还能做事？</td></tr><tr><td><a href="./16-inference-optimization-serving.html">第 16 课：推理优化和模型服务</a></td><td>如何让模型更快、更便宜、更稳定？</td></tr><tr><td><a href="./17-local-ai-ecosystem.html">第 17 课：本地 AI 生态</a></td><td>Ollama、llama.cpp、vLLM 等工具怎么选？</td></tr><tr><td><a href="./18-evaluation-costs-product.html">第 18 课：评估、成本和产品落地</a></td><td>如何判断一个 AI 功能是否值得上线？</td></tr></tbody></table><hr><h2 id="最终项目" tabindex="-1">最终项目 <a class="header-anchor" href="#最终项目" aria-label="Permalink to &quot;最终项目&quot;">​</a></h2><p>完成一个从 0 到 1 的 AI 知识库助手：</p><ol><li>准备业务文档。</li><li>清洗文档。</li><li>切 chunk。</li><li>生成 embedding。</li><li>存入向量数据库。</li><li>构建检索流程。</li><li>接入 LLM。</li><li>设计 system prompt。</li><li>加入引用来源。</li><li>做质量评估。</li><li>做成本估算。</li><li>部署成 API 或网页 Demo。</li></ol><p>最终你会理解：</p><blockquote><p>AI 产品不是只接一个模型 API，而是模型、数据、检索、工具、评估、成本和用户体验的组合系统。</p></blockquote>',34)])])}const u=a(r,[["render",d]]);export{b as __pageData,u as default};
